      "keystrokes": "mkdir -p output/safety\n",
      "duration": 0.1
    },
    {
      "keystrokes": "cat > output/safety/model-verification.json << 'EOF'
{
  "check": "model-pinning",
  "timestamp": "$(date -Iseconds)",
  "config_files": [
    ".claude/safety-checks.yaml",
    ".openclaw/safety-checks.yaml"
