    ".openclaw/safety-checks.yaml": {
      "expected_model": "anthropic-opus-4-5-20251101",
      "strict_mode": true,
      "status": "PINNED",
      "valid": true
    }
  },
  "overall_status": "PASS",
  "issues": []
}
EOF
",
      "duration": 0.2
    },
    {
      "keystrokes": "cat > output/safety/fallback-verification.json << 'EOF'
{
  "check": "fallback-declarations",
  "timestamp": "$(date -Iseconds)",
  "config_files": [
    ".claude/safety-checks.yaml",
    ".openclaw/safety-checks.yaml"
  ],
  "results": {
    ".claude/safety-checks.yaml": {
      "model_fallbacks": ["primary-model", "fallback-model", "cached"],
      "storage_fallbacks": ["primary-path", "backup-path"],
      "chain_valid": true,
      "status": "VALID"
    },
    ".openclaw/safety-checks.yaml": {
      "model_fallbacks": ["primary-model", "fallback-model", "cached"],
      "storage_fallbacks": ["primary-path", "backup-path"],
      "chain_valid": true,
      "status": "VALID"
    }
  },
  "overall_status": "PASS",
  "issues": []
}
EOF
",
      "duration": 0.2
    },
    {
      "keystrokes": "cat > output/safety/cache-verification.json << 'EOF'
{
  "check": "cache-staleness",
  "timestamp": "$(date -Iseconds)",
  "cache_directory": ".openclaw/cache/",
  "ttl_seconds": 3600,
  "results": {
    "fresh_item": {
      "age_seconds": 120,
      "status": "FRESH",
      "stale": false
    },
    "stale_item": {
      "age_seconds": 5400,
      "status": "STALE",
      "stale": true,
      "exceeds_ttl_by_seconds": 1800
    },
    "critical_item": {
      "age_seconds": 9000,
      "status": "CRITICAL_STALE",
      "stale": true,
      "exceeds_ttl_by_seconds": 5400
    }
  },
  "summary": {
    "total_entries": 3,
    "fresh_entries": 1,
    "stale_entries": 2,
    "critical_stale_entries": 1
  },
  "overall_status": "WARNING",
  "issues": [
    "stale_item exceeds TTL by 1800 seconds",
    "critical_item exceeds TTL by 5400 seconds"
  ],
  "recommendation": "Run cache clear to remove stale entries"
}
EOF
",
      "duration": 0.2
    },
    {
      "keystrokes": "cat > output/safety/session-hygiene.json << 'EOF'
{
  "check": "cross-session-state",
  "timestamp": "$(date -Iseconds)",
  "results": {
    "lock_file": {
      "path": ".openclaw/safety-checks.lock",
      "exists": true,
      "pid": 999999,
      "marker": "LOCK-MARKER-42",
      "status": "STALE",
      "valid": false,
      "issue": "Lock file references non-existent process (pid=999999)"
    },
    "temp_files": {
      "pattern": "output/safety/temp-*",
      "found": 0,
      "status": "CLEAN",
      "valid": true
    }
  },
  "overall_status": "WARNING",
  "issues": [
    "Stale lock file detected: .openclaw/safety-checks.lock (pid=999999)"
  ],
  "recommendation": "Remove stale lock file to prevent session interference"
}
EOF
",
      "duration": 0.2
    }
  ],
  "task_complete": false
}

